/*Table structure for table `room` */

DROP TABLE IF EXISTS `room`;

CREATE TABLE `room` (
  `room_id` bigint(20) NOT NULL COMMENT '房间id',
  `community_id` bigint(20) DEFAULT NULL COMMENT '小区id',
  `building_id` bigint(20) DEFAULT NULL COMMENT '楼栋id',
  `unit_id` bigint(20) DEFAULT NULL COMMENT '单元id',
  `room_level` int(11) DEFAULT NULL COMMENT '楼层',
  `room_code` varchar(32) DEFAULT NULL COMMENT '房间编号',
  `room_name` varchar(32) DEFAULT NULL COMMENT '房间名称',
  `room_acreage` decimal(32,10) DEFAULT NULL COMMENT '房屋建筑面积',
  `room_cost` decimal(32,10) DEFAULT NULL COMMENT '算费系数',
  `room_status` varchar(32) DEFAULT NULL COMMENT '房屋状态',
  `room_is_shop` varchar(32) DEFAULT NULL COMMENT '是否商铺',
  `room_s_commercial_house` varchar(32) DEFAULT NULL COMMENT '是否商品房',
  `room_house_type` varchar(32) DEFAULT NULL COMMENT '房屋户型',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`room_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='房间 ';

